import {
  BriefcaseBusiness,
  HomeIcon,
  Star,
  Sun,
  Moon,
} from "lucide-react";
import { useEffect, useState } from "react";
import { Link, useLocation } from "react-router-dom";

export default function Header() {
  const location = useLocation();

  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    const savedTheme = localStorage.getItem("theme");

    if (savedTheme === "dark") {
      setDarkMode(true);
      document.documentElement.classList.add("dark");
    }
  }, []);

  const toggleTheme = () => {
    const nextTheme = !darkMode;

    setDarkMode(nextTheme);

    if (nextTheme) {
      document.documentElement.classList.add("dark");
      localStorage.setItem("theme", "dark");
    } else {
      document.documentElement.classList.remove("dark");
      localStorage.setItem("theme", "light");
    }
  };

  const isHomeActive = location.pathname === "/";
  const isWorkActive = location.pathname === "/work";

  return (
    <header className="w-full">
      <nav className="flex items-center justify-between px-6 py-6 sm:px-8">

        {/* Navigation */}
        <div className="flex items-center gap-8">

          {/* Home */}
          <Link
            to="/"
            className={`flex items-center gap-2 text-[16px] transition-colors ${
              isHomeActive
                ? "font-medium text-neutral-950 dark:text-white"
                : "text-neutral-400 hover:text-neutral-950 dark:text-neutral-500 dark:hover:text-white"
            }`}
          >
            <HomeIcon
              className="h-4 w-4"
              strokeWidth={1.7}
            />

            <span>Home</span>
          </Link>

          {/* Work */}
          <Link
            to="/work"
            className={`flex items-center gap-2 text-[16px] transition-colors ${
              isWorkActive
                ? "font-medium text-neutral-950 dark:text-white"
                : "text-neutral-400 hover:text-neutral-950 dark:text-neutral-500 dark:hover:text-white"
            }`}
          >
            <BriefcaseBusiness
              className="h-4 w-4"
              strokeWidth={1.7}
            />

            <span>Work</span>
          </Link>

          {/* Side Projects */}
          <a
            href="#side-projects"
            className="flex items-center gap-2 text-[16px] text-neutral-400 transition-colors hover:text-neutral-950 dark:text-neutral-500 dark:hover:text-white"
          >
            <Star
              className="h-4 w-4"
              strokeWidth={1.7}
            />

            <span>Side projects</span>
          </a>

        </div>

        {/* Theme */}
        <button
          type="button"
          onClick={toggleTheme}
          aria-label="Toggle theme"
          className="flex h-9 w-9 items-center justify-center rounded-full text-neutral-500 transition-colors hover:bg-black/5 hover:text-neutral-950 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
        >
          {darkMode ? (
            <Sun
              className="h-[18px] w-[18px]"
              strokeWidth={1.7}
            />
          ) : (
            <Moon
              className="h-[18px] w-[18px]"
              strokeWidth={1.7}
            />
          )}
        </button>

      </nav>
    </header>
  );
}
